sksl:
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float time;
uniform float amount;
uniform float radius;
float4 readInput(float2 uv){if(uv.x<0.0||uv.y<0.0||uv.x>1.0||uv.y>1.0)return float4(0.0);return float4(image.eval(uv * size));}
half4 main(float2 coord){float2 p=((toLayer * float3(coord,1.0)).xy / layer)-float2(.5);float a=amount*max(0.0,1.0-length(p)/radius);float2 uv=float2x2(cos(a),-sin(a),sin(a),cos(a))*p+float2(.5);return readInput(((fromLayer * float3(uv * layer,1.0)).xy / size));}
